def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None:
        v = s.get('basic_structure_statistics', {}).get('volume_per_atom_A3')
    if v is not None and math.isfinite(v) and v > 0:
        return float(v)
    return 0.0

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    cubes = 0.0
    for e, x in s.get('composition', {}).items():
        r = props.get(e, {}).get('covalent_radius_A')
        if x is not None and x > 0 and r is not None and math.isfinite(r) and r > 0:
            total += x
            cubes += x * r * r * r
    if total <= 0:
        return 0.0
    return float(4.0 * math.pi * cubes / (3.0 * total * v))

def feature(s):
    v = s.get('volume_per_atom_A3')
    if v is None or not math.isfinite(v) or v <= 0:
        return 0.0
    props = s.get('element_properties', {})
    total = 0.0
    electrons = 0.0
    for e, x in s.get('composition', {}).items():
        z = props.get(e, {}).get('valence_electrons')
        if x is not None and x > 0 and z is not None and math.isfinite(z):
            total += x
            electrons += x * z
    if total <= 0:
        return 0.0
    return float(electrons / (total * v))

def feature(s):
    sites = s.get('sites', [])
    n = len(sites)
    nearest = [7.0 for a in sites]
    for b in s.get('neighbors', []):
        i = b['i']
        d = b['distance_A']
        if 0 <= i < n and d > 0 and d < nearest[i]:
            nearest[i] = d
    total = 0.0
    first = 0.0
    second = 0.0
    for i in range(n):
        if nearest[i] < 7.0:
            o = max(0.0, float(sites[i].get('occupancy', 1.0) or 0.0))
            total += o
            first += o * nearest[i]
            second += o * nearest[i] * nearest[i]
    if total <= 0 or first <= 0:
        return 0.0
    mean = first / total
    return float(math.sqrt(max(0.0, second / total - mean * mean)) / mean)

def feature(s):
    sites = s.get('sites', [])
    n = len(sites)
    occ = [max(0.0, float(a.get('occupancy', 1.0) or 0.0)) for a in sites]
    nearest = [7.0 for a in sites]
    neighbors = s.get('neighbors', [])
    for b in neighbors:
        i = b['i']
        d = b['distance_A']
        if 0 <= i < n and d > 0 and d < nearest[i]:
            nearest[i] = d
    cn = [0.0 for a in sites]
    for b in neighbors:
        i = b['i']
        j = b['j']
        d = b['distance_A']
        if 0 <= i < n and 0 <= j < n and d > 0 and d <= 1.8 * nearest[i]:
            cn[i] += occ[j] * math.exp(1.0 - (d / nearest[i]) ** 6)
    total = sum(occ)
    if total <= 0:
        return 0.0
    mean = sum(occ[i] * cn[i] for i in range(n)) / total
    return float(math.sqrt(sum(occ[i] * (cn[i] - mean) ** 2 for i in range(n)) / total))

def feature(s):
    sites = s.get('sites', [])
    n = len(sites)
    props = s.get('element_properties', {})
    best = 3.0
    for b in s.get('neighbors', []):
        i = b['i']
        j = b['j']
        d = b['distance_A']
        if 0 <= i < n and 0 <= j < n and d > 0:
            e = sites[i].get('element', '')
            if e == sites[j].get('element', ''):
                p = props.get(e, {})
                chi = p.get('eneg')
                r = p.get('covalent_radius_A')
                oi = sites[i].get('occupancy', 1.0) or 0.0
                oj = sites[j].get('occupancy', 1.0) or 0.0
                if chi is not None and r is not None and math.isfinite(chi) and math.isfinite(r) and chi >= 2.4 and r > 0 and oi > 0 and oj > 0:
                    best = min(best, d / (2.0 * r))
    return float(best)
